module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [63:0] adda_reg [0:7];
reg [63:0] addb_reg [0:7];
reg [64:0] result_reg [0:7];
reg [6:0] carry_in_reg [0:7];
reg o_en_reg [0:7];

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[0] <= 64'd0;
        addb_reg[0] <= 64'd0;
        result_reg[0] <= 65'd0;
        carry_in_reg[0] <= 7'd0;
        o_en_reg[0] <= 1'b0;
    end else begin
        adda_reg[0] <= adda;
        addb_reg[0] <= addb;
        result_reg[0] <= adda_reg[0] + addb_reg[0] + carry_in_reg[0][0];
        carry_in_reg[0][1] <= result_reg[0][64];
        o_en_reg[0] <= i_en;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[1] <= 64'd0;
        addb_reg[1] <= 64'd0;
        result_reg[1] <= 65'd0;
        carry_in_reg[1] <= 7'd0;
        o_en_reg[1] <= 1'b0;
    end else begin
        adda_reg[1] <= adda_reg[0];
        addb_reg[1] <= addb_reg[0];
        result_reg[1] <= adda_reg[1] + addb_reg[1] + carry_in_reg[1][0];
        carry_in_reg[1][1] <= result_reg[1][64];
        o_en_reg[1] <= o_en_reg[0];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[2] <= 64'd0;
        addb_reg[2] <= 64'd0;
        result_reg[2] <= 65'd0;
        carry_in_reg[2] <= 7'd0;
        o_en_reg[2] <= 1'b0;
    end else begin
        adda_reg[2] <= adda_reg[1];
        addb_reg[2] <= addb_reg[1];
        result_reg[2] <= adda_reg[2] + addb_reg[2] + carry_in_reg[2][0];
        carry_in_reg[2][1] <= result_reg[2][64];
        o_en_reg[2] <= o_en_reg[1];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[3] <= 64'd0;
        addb_reg[3] <= 64'd0;
        result_reg[3] <= 65'd0;
        carry_in_reg[3] <= 7'd0;
        o_en_reg[3] <= 1'b0;
    end else begin
        adda_reg[3] <= adda_reg[2];
        addb_reg[3] <= addb_reg[2];
        result_reg[3] <= adda_reg[3] + addb_reg[3] + carry_in_reg[3][0];
        carry_in_reg[3][1] <= result_reg[3][64];
        o_en_reg[3] <= o_en_reg[2];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[4] <= 64'd0;
        addb_reg[4] <= 64'd0;
        result_reg[4] <= 65'd0;
        carry_in_reg[4] <= 7'd0;
        o_en_reg[4] <= 1'b0;
    end else begin
        adda_reg[4] <= adda_reg[3];
        addb_reg[4] <= addb_reg[3];
        result_reg[4] <= adda_reg[4] + addb_reg[4] + carry_in_reg[4][0];
        carry_in_reg[4][1] <= result_reg[4][64];
        o_en_reg[4] <= o_en_reg[3];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[5] <= 64'd0;
        addb_reg[5] <= 64'd0;
        result_reg[5] <= 65'd0;
        carry_in_reg[5] <= 7'd0;
        o_en_reg[5] <= 1'b0;
    end else begin
        adda_reg[5] <= adda_reg[4];
        addb_reg[5] <= addb_reg[4];
        result_reg[5] <= adda_reg[5] + addb_reg[5] + carry_in_reg[5][0];
        carry_in_reg[5][1] <= result_reg[5][64];
        o_en_reg[5] <= o_en_reg[4];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[6] <= 64'd0;
        addb_reg[6] <= 64'd0;
        result_reg[6] <= 65'd0;
        carry_in_reg[6] <= 7'd0;
        o_en_reg[6] <= 1'b0;
    end else begin
        adda_reg[6] <= adda_reg[5];
        addb_reg[6] <= addb_reg[5];
        result_reg[6] <= adda_reg[6] + addb_reg[6] + carry_in_reg[6][0];
        carry_in_reg[6][1] <= result_reg[6][64];
        o_en_reg[6] <= o_en_reg[5];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[7] <= 64'd0;
        addb_reg[7] <= 64'd0;
        result_reg[7] <= 65'd0;
        carry_in_reg[7] <= 7'd0;
        o_en_reg[7] <= 1'b0;
    end else begin
        adda_reg[7] <= adda_reg[6];
        addb_reg[7] <= addb_reg[6];
        result_reg[7] <= adda_reg[7] + addb_reg[7] + carry_in_reg[7][0];
        carry_in_reg[7][1] <= result_reg[7][64];
        o_en_reg[7] <= o_en_reg[6];
    end
end

assign o_en = o_en_reg[7];
assign result = result_reg[7];
endmodule

module verified_adder_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg stage1;
reg stage2;
reg stage3;

wire [STG_WIDTH-1:0] a1;
wire [STG_WIDTH-1:0] b1;
wire [STG_WIDTH-1:0] a2;
wire [STG_WIDTH-1:0] b2;
wire [STG_WIDTH-1:0] a3;
wire [STG_WIDTH-1:0] b3;
wire [STG_WIDTH-1:0] a4;
wire [STG_WIDTH-1:0] b4;

reg [STG_WIDTH-1:0] a2_ff1;
reg [STG_WIDTH-1:0] b2_ff1;

reg [STG_WIDTH-1:0] a3_ff1;
reg [STG_WIDTH-1:0] b3_ff1;
reg [STG_WIDTH-1:0] a3_ff2;
reg [STG_WIDTH-1:0] b3_ff2;

reg [STG_WIDTH-1:0] a4_ff1;
reg [STG_WIDTH-1:0] b4_ff1;
reg [STG_WIDTH-1:0] a4_ff2;
reg [STG_WIDTH-1:0] b4_ff2;
reg [STG_WIDTH-1:0] a4_ff3;
reg [STG_WIDTH-1:0] b4_ff3;

reg c1;
reg c2;
reg c3;
reg c4;

reg [STG_WIDTH-1:0] s1;
reg [STG_WIDTH-1:0] s2;
reg [STG_WIDTH-1:0] s3;
reg [STG_WIDTH-1:0] s4;

reg [STG_WIDTH-1:0] s1_ff1;
reg [STG_WIDTH-1:0] s1_ff2;
reg [STG_WIDTH-1:0] s1_ff3;

reg [STG_WIDTH-1:0] s2_ff1;
reg [STG_WIDTH-1:0] s2_ff2;

reg [STG_WIDTH-1:0] s3_ff1;

assign a1 = adda[STG_WIDTH-1:0];
assign b1 = addb[STG_WIDTH-1:0];
assign a2 = adda[STG_WIDTH*2-1:16];
assign b2 = addb[STG_WIDTH*2-1:16];
assign a3 = adda[STG_WIDTH*3-1:32];
assign b3 = addb[STG_WIDTH*3-1:32];
assign a4 = adda[STG_WIDTH*4-1:48];
assign b4 = addb[STG_WIDTH*4-1:48];

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        stage1 <= 1'b0;
        stage2 <= 1'b0;
        stage3 <= 1'b0;
        o_en <= 1'b0;
    end
    else begin
        stage1 <= i_en;
        stage2 <= stage1;
        stage3 <= stage2;
        o_en <= stage3;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        a2_ff1 <= 'd0;
        b2_ff1 <= 'd0;
        a3_ff1 <= 'd0;
        b3_ff1 <= 'd0;
        a3_ff2 <= 'd0;
        b3_ff2 <= 'd0;
        a4_ff1 <= 'd0;
        b4_ff1 <= 'd0;
        a4_ff2 <= 'd0;
        b4_ff2 <= 'd0;
        a4_ff3 <= 'd0;
        b4_ff3 <= 'd0;
    end
    else begin
        a2_ff1 <= a2;
        b2_ff1 <= b2;
        a3_ff1 <= a3;
        b3_ff1 <= b3;
        a3_ff2 <= a3_ff1;
        b3_ff2 <= b3_ff1;
        a4_ff1 <= a4;
        b4_ff1 <= b4;
        a4_ff2 <= a4_ff1;
        b4_ff2<= b4_ff1;
        a4_ff3 <= a4_ff2;
        b4_ff3 <= b4_ff2;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        s1_ff1 <= 'd0;
        s1_ff2 <= 'd0;
        s1_ff3 <= 'd0;
        s2_ff1 <= 'd0;
        s2_ff2 <= 'd0;
        s3_ff1 <= 'd0;
    end
    else begin
        s1_ff1 <= s1;
        s1_ff2 <= s1_ff1;
        s1_ff3 <= s1_ff2;
        s2_ff1 <= s2;
        s2_ff2 <= s2_ff1;
        s3_ff1 <= s3;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c1 <= 1'b0;
        s1 <= 'd0;
    end
    else if (i_en) begin
        {c1, s1} <= a1 + b1;
    end
    else begin
        c1 <= c1;
        s1 <= s1;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c2 <= 1'b0;
        s2 <= 'd0;
    end
    else if (stage1) begin
        {c2, s2} <= a2_ff1 + b2_ff1 + c1;
    end
    else begin
        c2 <= c2;
        s2 <= s2;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c3 <= 1'b0;
        s3 <= 'd0;
    end
    else if (stage2) begin
        {c3, s3} <= a3_ff2 + b3_ff2 + c2;
    end
    else begin
        c3 <= c3;
        s3 <= s3;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c4 <= 1'b0;
        s4 <= 'd0;
    end
    else if (stage3) begin
        {c4, s4} <= a4_ff3 + b4_ff3 + c3;
    end
    else begin
        c4 <= c4;
        s4 <= s4;
    end
end

assign result = {c4, s4, s3_ff1, s2_ff2, s1_ff3};

endmodule
